func (q *Queries) ListThread(ctx context.Context, arg ListThreadParams) ([]ListThreadRow, error) {
	rows, err := q.db.Query(ctx, listThread, arg.TenantID, arg.OwnerID, arg.ThreadKey)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListThreadRow
	for rows.Next() {
		var i ListThreadRow
		if err := rows.Scan(
			&i.Direction,
			&i.ID,
			&i.Subject,
			&i.Body,
			&i.BodyFormat,
			&i.Counterparty,
			&i.Who,
			&i.At,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

