const setMailAccountSecret = `-- name: SetMailAccountSecret :exec
UPDATE mail_accounts
SET secret_enc = $1::bytea,
    key_version = $2::int,
    auth_kind = 'PASSWORD',
    oauth_refresh_enc = ''::bytea,
    verified_at = NULL,
    last_error = '',
    updated_at = now()
WHERE tenant_id = $3::bigint AND id = $4::bigint
`

type SetMailAccountSecretParams struct {
	SecretEnc  []byte
	KeyVersion int32
	TenantID   int64
	ID         int64
}

// Storing a new secret invalidates any previous verification: the code may
// be wrong, and claiming a mailbox works because an older one did is exactly
// the kind of stale green tick that stops people trusting the indicator.
// Typing a code also decides how this account authenticates from now on:
// auth_kind flips back to PASSWORD and any Google grant is dropped — the
// mirror image of SetMailAccountOAuth clearing secret_enc.
func (q *Queries) SetMailAccountSecret(ctx context.Context, arg SetMailAccountSecretParams) error {
	_, err := q.db.Exec(ctx, setMailAccountSecret,
		arg.SecretEnc,
		arg.KeyVersion,
		arg.TenantID,
		arg.ID,
	)
	return err
}

