const setThreadFlags = `-- name: SetThreadFlags :many
UPDATE email_inbound
SET is_read    = coalesce($1::boolean, is_read),
    is_starred = coalesce($2::boolean, is_starred),
    not_junk   = coalesce($3::boolean, not_junk),
    archived_at = CASE
        WHEN $4::boolean IS NULL THEN archived_at
        WHEN $4::boolean THEN coalesce(archived_at, now())
        ELSE NULL END,
    deleted_at = CASE
        WHEN $5::boolean IS NULL THEN deleted_at
        WHEN $5::boolean THEN coalesce(deleted_at, now())
        ELSE NULL END
WHERE tenant_id = $6::bigint
  AND owner_id = $7::bigint
  AND thread_key = $8::text
  AND thread_key <> ''
RETURNING account_id, folder, imap_uid, is_read, is_starred, message_id, archived_at, deleted_at, not_junk
`

type SetThreadFlagsParams struct {
	Read      *bool
	Starred   *bool
	NotJunk   *bool
	Archived  *bool
	Deleted   *bool
	TenantID  int64
	OwnerID   int64
	ThreadKey string
}

type SetThreadFlagsRow struct {
	AccountID  int64
	Folder     string
	ImapUid    int64
	IsRead     bool
	IsStarred  bool
	MessageID  string
	ArchivedAt pgtype.Timestamptz
	DeletedAt  pgtype.Timestamptz
	NotJunk    bool
}

// Housekeeping applied to a whole conversation. Archiving from a page that
// shows the entire exchange has to move the entire exchange; otherwise the
// thread stays in the inbox one message lighter, which reads as a bug.
// Owner-scoped: thread keys are guessable, so this must never reach further
// than the caller's own mail.
func (q *Queries) SetThreadFlags(ctx context.Context, arg SetThreadFlagsParams) ([]SetThreadFlagsRow, error) {
	rows, err := q.db.Query(ctx, setThreadFlags,
		arg.Read,
		arg.Starred,
		arg.NotJunk,
		arg.Archived,
		arg.Deleted,
		arg.TenantID,
		arg.OwnerID,
		arg.ThreadKey,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SetThreadFlagsRow
	for rows.Next() {
		var i SetThreadFlagsRow
		if err := rows.Scan(
			&i.AccountID,
			&i.Folder,
			&i.ImapUid,
			&i.IsRead,
			&i.IsStarred,
			&i.MessageID,
			&i.ArchivedAt,
			&i.DeletedAt,
			&i.NotJunk,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const syncAccountHostsFromTenant = `-- name: SyncAccountHostsFromTenant :execrows
UPDATE mail_accounts a
   SET domain = h.domain,
       smtp_host = h.smtp_host, smtp_port = h.smtp_port, smtp_security = h.smtp_security,
       imap_host = h.imap_host, imap_port = h.imap_port, imap_security = h.imap_security,
       hourly_quota = h.hourly_quota, daily_quota = h.daily_quota,
       updated_at = now()
  FROM mail_hosts h
 WHERE h.tenant_id = a.tenant_id
   AND a.tenant_id = $1::bigint
`

// 把租户级的收发服务器配置刷到该租户所有账号行上。
//
// 只在这一期存在。00042 把主机搬到了账号上，而设置页这一版还在写
// mail_hosts——不同步的话，管理员改完 SMTP 地址会发现「改了没生效」，
// 而且没有任何报错。第二期设置页改成按信箱之后，这句和它的调用点一起删。
func (q *Queries) SyncAccountHostsFromTenant(ctx context.Context, tenantID int64) (int64, error) {
	result, err := q.db.Exec(ctx, syncAccountHostsFromTenant, tenantID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const syncStarredFromHost = `-- name: SyncStarredFromHost :execrows
UPDATE email_inbound
SET is_starred = (imap_uid = ANY($1::bigint[]))
WHERE tenant_id = $2::bigint
  AND account_id = $3::bigint
  AND folder = $4::text
  AND NOT not_junk
  AND is_starred <> (imap_uid = ANY($1::bigint[]))
`

type SyncStarredFromHostParams struct {
	StarredUids []int64
	TenantID    int64
	AccountID   int64
	Folder      string
}

// Makes the ERP's stars agree with the host's, over the whole folder at once.
//
// Stars used to ride along with the read-state reconcile, which fetches flags
// for the newest 200 UIDs. That window is a few days of a busy mailbox, so a
// star put on anything older in Gmail simply never arrived — the symptom was
// a mailbox full of stars showing exactly one in the ERP.
//
// A single UID SEARCH FLAGGED answers the question for the entire folder in
// one round trip, which is why this can be a plain assignment rather than a
// per-message comparison: starred is "in the set the host just named".
//
// Rescued junk is left alone. Those rows still carry their old JUNK folder and
// UID while the message itself has moved to the host's inbox, so the search
// would not name them and this would quietly unstar them.
//
// The final predicate keeps the update to rows that actually change, so a
// mailbox with no star activity costs nothing every two minutes.
func (q *Queries) SyncStarredFromHost(ctx context.Context, arg SyncStarredFromHostParams) (int64, error) {
	result, err := q.db.Exec(ctx, syncStarredFromHost,
		arg.StarredUids,
		arg.TenantID,
		arg.AccountID,
		arg.Folder,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const trashJunkView = `-- name: TrashJunkView :many
UPDATE email_inbound
SET deleted_at = now()
WHERE tenant_id = $1::bigint
  AND owner_id = $2::bigint
  AND folder = 'JUNK'
  AND NOT not_junk
  AND deleted_at IS NULL
RETURNING id, account_id, folder, imap_uid, message_id
`

type TrashJunkViewParams struct {
	TenantID int64
	OwnerID  int64
}

type TrashJunkViewRow struct {
	ID        int64
	AccountID int64
	Folder    string
	ImapUid   int64
	MessageID string
}

// Empties the junk view into the trash in one go.
//
// Scoped exactly like the junk list: a mail somebody has already rescued with
// 「这不是垃圾」 is not junk any more and must not be swept up with the rest.
// Every touched row comes back so the deletion can be carried to the host too,
// the same as deleting one by hand.
func (q *Queries) TrashJunkView(ctx context.Context, arg TrashJunkViewParams) ([]TrashJunkViewRow, error) {
	rows, err := q.db.Query(ctx, trashJunkView, arg.TenantID, arg.OwnerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TrashJunkViewRow
	for rows.Next() {
		var i TrashJunkViewRow
		if err := rows.Scan(
			&i.ID,
			&i.AccountID,
			&i.Folder,
			&i.ImapUid,
			&i.MessageID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertMailAccountShell = `-- name: UpsertMailAccountShell :one
INSERT INTO mail_accounts (
    tenant_id, employee_id, email, username, secret_enc, key_version, updated_at
) VALUES (
    $1::bigint, $2::bigint,
    $3::text, $4::text, ''::bytea, 0, now()
)
ON CONFLICT (tenant_id, employee_id) DO UPDATE SET
    email = excluded.email,
    username = excluded.username,
    updated_at = now()
RETURNING id
`

type UpsertMailAccountShellParams struct {
	TenantID   int64
	EmployeeID int64
	Email      string
	Username   string
}

// Creates or updates everything except the secret, and returns the id.
//
// Split from the secret write because the ciphertext is bound to the row id
// (see AccountAAD), which does not exist until the row does. Insert first,
// seal against the real id, then store — rather than inventing the id
// client-side or binding to something weaker.
func (q *Queries) UpsertMailAccountShell(ctx context.Context, arg UpsertMailAccountShellParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertMailAccountShell,
		arg.TenantID,
		arg.EmployeeID,
		arg.Email,
		arg.Username,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}

