const upsertSyncState = `-- name: UpsertSyncState :exec
INSERT INTO mail_sync_state (tenant_id, account_id, folder, uid_validity, last_uid, low_uid, last_synced_at, last_error)
VALUES ($1::bigint, $2::bigint, $3::text,
        $4::bigint, $5::bigint, $6::bigint, now(), '')
ON CONFLICT (tenant_id, account_id, folder) DO UPDATE SET
    uid_validity = excluded.uid_validity,
    last_uid = excluded.last_uid,
    low_uid = CASE
        WHEN mail_sync_state.low_uid = 0 THEN excluded.low_uid
        WHEN excluded.low_uid = 0 THEN mail_sync_state.low_uid
        ELSE LEAST(mail_sync_state.low_uid, excluded.low_uid)
    END,
    last_synced_at = now(),
    last_error = ''
`

type UpsertSyncStateParams struct {
	TenantID    int64
	AccountID   int64
	Folder      string
	UidValidity int64
	LastUid     int64
	LowUid      int64
}

// low_uid only ever moves down: 0 means backfill has not started, so the
// first write sets it and later writes keep the minimum.
func (q *Queries) UpsertSyncState(ctx context.Context, arg UpsertSyncStateParams) error {
	_, err := q.db.Exec(ctx, upsertSyncState,
		arg.TenantID,
		arg.AccountID,
		arg.Folder,
		arg.UidValidity,
		arg.LastUid,
		arg.LowUid,
	)
	return err
}
